//! Browser interface generated by wasm-bindgen over the shared task board.

#[cfg(all(target_arch = "wasm32", target_os = "unknown"))]
pub mod bind {
    use shared_tasks::Board;
    use wasm_bindgen::prelude::*;

    #[wasm_bindgen]
    pub struct WebBoard {
        board: Board,
    }

    #[wasm_bindgen]
    impl WebBoard {
        #[wasm_bindgen(constructor)]
        pub fn new(text: &str) -> Result<WebBoard, JsError> {
            Board::load(text)
                .map(|board| WebBoard { board })
                .map_err(|error| JsError::new(&format!("err:{}", error.kind())))
        }

        pub fn apply(&mut self, command: &str) -> String {
            shared_tasks::reply(&mut self.board, command)
        }

        pub fn lines(&self) -> Vec<String> {
            self.board.render()
        }

        pub fn summary(&self) -> String {
            self.board.summary().to_string()
        }

        pub fn save(&self) -> String {
            self.board.save()
        }
    }

    #[wasm_bindgen]
    pub fn asset_report(name: &str, bytes: &[u8]) -> String {
        shared_tasks::asset_report(name, bytes)
    }

    #[wasm_bindgen]
    pub fn core_version() -> String {
        shared_tasks::CORE_VERSION.to_owned()
    }
}
